  function openCourseFromBrowser(id) {
    if (!registry[id]) return;
    if (openDocIds.indexOf(id) === -1) { openDocIds.push(id); saveOpenDocIds(openDocIds); renderTabs(); }
    closeBrowser();
    if (id !== activeDocId) switchDoc(id);
  }

  // #74 card actions — all reuse the existing single-source logic (registry +
  // saveRegistry choke point), just wrapped behind the browser's cards/menu.
  function uniqueCopyCode(baseCode) {
    var base = (baseCode || "COURSE") + "-copy", code = base, n = 1;
    while (registry[code]) { n++; code = base + "-" + n; }
    return code;
  }
  function duplicateCourse(id) {
    var srcDoc = registry[id]; if (!srcDoc) return;
    var copy = JSON.parse(JSON.stringify(srcDoc)); // keep asset:<id> refs (media stays in the shared store)
    if (!copy.meta) copy.meta = {};
    copy.meta.code = uniqueCopyCode(srcDoc.meta && srcDoc.meta.code);
    copy.meta.title = ((srcDoc.meta && srcDoc.meta.title) || "Untitled") + " (Copy)";
    delete copy.meta.lastOpenedAt;
    stampDocUpdatedAt(copy, Date.now());
    registry[copy.meta.code] = copy;
    saveRegistry(registry);
    renderBrowserGrid();
  }
  function renameCourse(id) {
    var d = registry[id]; if (!d) return;
    promptModal("Rename course", "Course title", (d.meta && d.meta.title) || "", function (val) {
      val = (val || "").trim(); if (!val) return;
      if (!d.meta) d.meta = {};
      d.meta.title = val;
      stampDocUpdatedAt(d, Date.now());
      saveRegistry(registry);
      if (id === activeDocId) renderTabs();
      renderBrowserGrid();
    });
  }
  function deleteCourse(id) {
    var d = registry[id]; if (!d) return;
    confirmModal("Delete course?",
      "Permanently remove “" + ((d.meta && d.meta.title) || id) + "” (" + id + ") from this machine. This can't be undone. Any exported SCORM or backup folder on disk is not affected.",
      function () {
        delete registry[id];
        var oi = openDocIds.indexOf(id);
        if (oi !== -1) openDocIds.splice(oi, 1);
        if (id === activeDocId) {
          var next = openDocIds[0] || Object.keys(registry)[0];
          if (!next) { var fresh = clone(window.SAMPLE_DOC); registry[fresh.meta.code] = fresh; next = fresh.meta.code; }
          if (openDocIds.indexOf(next) === -1) openDocIds.push(next);
          activeDocId = next; saveActiveDocId(activeDocId); doc = registry[next];
          undoStack = []; redoStack = []; clearSelection(); clearMultiPages(); multiSel = []; currentPage = 0;
          mount();
        }
        saveOpenDocIds(openDocIds);
        saveRegistry(registry);
        renderTabs();
        renderBrowserGrid();
      }, { danger: true, okLabel: "Delete" });
  }
  function showCourseMenu(x, y, id) {
    if (!registry[id]) return;
    showContextMenu(x, y, [
      { label: "Open", onClick: function () { openCourseFromBrowser(id); } },
      { label: "Duplicate", onClick: function () { duplicateCourse(id); } },
      { label: "Rename…", onClick: function () { renameCourse(id); } },
      { sep: true },
      { label: "Export .verso", onClick: function () { exportVersoPackage(registry[id]); } },
      { sep: true },
      { label: "Delete", danger: true, onClick: function () { deleteCourse(id); } }
    ]);
  }

  function buildBrowserEmpty() {
    var wrap = h("div", "vbrowser-empty");
    var querying = !!browserQuery;
    wrap.appendChild(h("div", "vbrowser-empty__title", querying ? "No matching courses" : "No courses yet"));
    wrap.appendChild(h("div", "vbrowser-empty__hint",
      querying ? "No course title or code matches your search." : "Create a new course or import a .verso to get started."));
    if (!querying) {
      var b = h("button", "vbrowser__btn vbrowser__btn--primary", "New course");
      b.addEventListener("click", function () { closeBrowser(); showNewDocDialog(); });
      wrap.appendChild(b);
    }
    return wrap;
  }

  function observeThumbs(cards) {
    if (thumbObserver) { thumbObserver.disconnect(); thumbObserver = null; }
    if (typeof IntersectionObserver === "undefined" || !browserUI) {
      cards.forEach(function (c) { if (c.__thumb) c.__thumb.__renderThumb(); });
      return;
    }
    thumbObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting && en.target.__thumb) { en.target.__thumb.__renderThumb(); thumbObserver.unobserve(en.target); }
      });
    }, { root: browserUI.grid, rootMargin: "300px" });
    cards.forEach(function (c) { thumbObserver.observe(c); });
  }

  function renderBrowserGrid() {
    if (!browserUI) return;
    var grid = browserUI.grid; grid.innerHTML = "";
    var ids = Object.keys(registry).filter(function (id) { return courseMatchesQuery(registry[id], browserQuery); });
    ids.sort(function (x, y) { return recentsCompare(registry[x], registry[y]); });
    if (!ids.length) { grid.appendChild(buildBrowserEmpty()); return; }
    var cards = ids.map(function (id) { var c = buildBrowserCard(id, registry[id]); grid.appendChild(c); return c; });
    observeThumbs(cards);
  }

  function ensureBrowser() {
    if (browserUI) return browserUI;
    var overlay = h("div", "vbrowser"); overlay.id = "vbrowser"; overlay.hidden = true;
    var bar = h("div", "vbrowser__bar");
    bar.appendChild(h("div", "vbrowser__title", "Courses"));
    var search = h("label", "vbrowser__search");
    search.innerHTML = Icon("search");
    var input = h("input", "vbrowser__search-input"); input.type = "text"; input.placeholder = "search courses";
    input.addEventListener("input", function () { browserQuery = input.value; renderBrowserGrid(); });
    search.appendChild(input);
    bar.appendChild(search);
    var spacer = h("div", "vbrowser__spacer"); bar.appendChild(spacer);
    var importBtn = h("button", "vbrowser__btn", "Import");
    importBtn.addEventListener("click", function () {
      pickCourseFile(function (imported) { importDocToRegistry(imported); closeBrowser(); });
    });
    bar.appendChild(importBtn);
    var newBtn = h("button", "vbrowser__btn vbrowser__btn--primary", "New course");
    newBtn.addEventListener("click", function () { closeBrowser(); showNewDocDialog(); });
    bar.appendChild(newBtn);
    var closeBtn = iconBtn("x", "Close (Esc)"); closeBtn.classList.add("vbrowser__close");
    closeBtn.addEventListener("click", closeBrowser);
    bar.appendChild(closeBtn);
    var grid = h("div", "vbrowser__grid");
    overlay.appendChild(bar); overlay.appendChild(grid);
    document.body.appendChild(overlay);
    browserUI = { overlay: overlay, grid: grid, input: input };
    return browserUI;
  }

  function openBrowser() {
    ensureBrowser();
    browserQuery = ""; browserUI.input.value = "";
    browserUI.overlay.hidden = false;
    document.body.classList.add("vbrowser-open");
    renderBrowserGrid();
    setTimeout(function () { try { browserUI.input.focus(); } catch (_) {} }, 0);
  }
  function closeBrowser() {
    if (!browserUI) return;
    browserUI.overlay.hidden = true;
    document.body.classList.remove("vbrowser-open");
    if (thumbObserver) { thumbObserver.disconnect(); thumbObserver = null; }
  }
  function browserIsOpen() { return !!(browserUI && !browserUI.overlay.hidden); }

  (function wireHome() {
    var b = document.getElementById("home-btn");
    if (b) b.addEventListener("click", openBrowser);
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && browserIsOpen()) { e.preventDefault(); closeBrowser(); }
    });
  })();

  // ---- #75 Save / recents menu (top-bar dropdown) ---------------------------
  // A condensed version of the browser for quick access without leaving the
  // editor: recent courses (mini snapshots), Save as a copy (duplicate into the
  // library), Open (import .verso), and a read-only "where are my files" store
  // path. Reuses the same recents/thumbnail/duplicate/import single-source paths.
  var saveMenuEl = null;
  function onSaveMenuOutside(e) {
    if (saveMenuEl && !saveMenuEl.contains(e.target) && e.target.id !== "save-menu-btn") closeSaveMenu();
  }
  function closeSaveMenu() {
    if (!saveMenuEl) return;
    saveMenuEl.remove(); saveMenuEl = null;
    document.removeEventListener("mousedown", onSaveMenuOutside, true);
  }
  function storeLocationText() {
    var backend = "browser";
    try { backend = localStorage.getItem(STORAGE_BACKEND_KEY) || "browser"; } catch (_) {}
    return backend === "file"
      ? "~/Library/Application Support/Verso/store"
      : "This browser (localStorage + IndexedDB)";
  }
  function openSaveMenu(anchor) {
    closeSaveMenu();
    var menu = h("div", "vsavemenu");
    menu.appendChild(h("div", "vsavemenu__head", "Recent courses"));
    var ids = Object.keys(registry).sort(function (a, b) { return recentsCompare(registry[a], registry[b]); }).slice(0, 6);
    if (!ids.length) menu.appendChild(h("div", "vsavemenu__empty", "No courses yet"));
    ids.forEach(function (id) {
      var d = registry[id];
      var row = h("div", "vsavemenu__row" + (id === activeDocId ? " is-active" : ""));
      var thumb = renderCourseThumb(d); thumb.classList.add("vsavemenu__thumb");
      var main = h("div", "vsavemenu__main");
      var t = h("div", "vsavemenu__title", (d.meta && d.meta.title) || id); t.title = t.textContent;
      main.appendChild(t); main.appendChild(h("div", "vsavemenu__code", (d.meta && d.meta.code) || id));
      row.appendChild(thumb); row.appendChild(main);
      row.appendChild(h("div", "vsavemenu__when", formatRelativeTime(d.meta && d.meta.updatedAt, Date.now())));
      row.addEventListener("click", function () { closeSaveMenu(); openCourseFromBrowser(id); });
      menu.appendChild(row);
      thumb.__renderThumb(); // few rows -> render eagerly
    });
    menu.appendChild(h("div", "vsavemenu__sep"));
    function action(label, fn) {
      var a = h("div", "vsavemenu__action", label);
      a.addEventListener("click", function () { closeSaveMenu(); fn(); });
      menu.appendChild(a);
    }
    action("Save as a copy", function () { if (activeDocId) duplicateCourse(activeDocId); });
    action("Open…", function () { pickCourseFile(function (imported) { importDocToRegistry(imported); }); });
    action("Promote to Product…", function () { promoteToProductModal(); });
    if (doc && doc.meta && doc.meta.productId && window.ProductsStore[doc.meta.productId]) {
      action("Remove from Product", function () {
        var pname = window.ProductsStore[doc.meta.productId].name || "this Product";
        confirmModal("Remove from Product?", "Unlinks this course from “" + pname + "”. The course and its content stay -- only the Product tag is removed.", function () { unlinkDocFromProduct(doc); mountProductPicker(); }, { okLabel: "Remove", danger: true });
      });
    }
    menu.appendChild(h("div", "vsavemenu__sep"));
    menu.appendChild(h("div", "vsavemenu__head", "Where are my files"));
    menu.appendChild(h("div", "vsavemenu__path", storeLocationText()));
    document.body.appendChild(menu);
    var r = anchor.getBoundingClientRect();
    var top = r.bottom + 6;
    if (top + menu.offsetHeight > window.innerHeight - 8) top = Math.max(8, r.top - menu.offsetHeight - 6);
    menu.style.top = top + "px";
    menu.style.left = Math.max(8, Math.min(r.right - menu.offsetWidth, window.innerWidth - menu.offsetWidth - 8)) + "px";
    saveMenuEl = menu;
    setTimeout(function () { document.addEventListener("mousedown", onSaveMenuOutside, true); }, 0);
  }
  function saveMenuIsOpen() { return !!saveMenuEl; }
  (function wireSaveMenu() {
    var b = document.getElementById("save-menu-btn");
    if (b) b.addEventListener("click", function () { if (saveMenuEl) closeSaveMenu(); else openSaveMenu(b); });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && saveMenuIsOpen()) { e.preventDefault(); closeSaveMenu(); }
    });
  })();

  // ---- Shared "header & footer default for new courses" ---------------------
  // A machine-level default (localStorage, cross-project) captured from any course's
  // Header & Footer, applied as the starting header/footer of every NEW course. The
  // pure core sanitises what carries: the per-course header TITLE is dropped (each
  // new course uses its own name) and any courseNav SECTIONS are cleared (nav is
  // chapter-derived at render, so styling carries but not the source course's page
  // bindings). The logo asset ref is baked to an inline data URI by the caller so the
  // default is self-contained (survives asset GC + isn't tied to the source course).
  var HF_DEFAULT_KEY = "authoring.defaultHeaderFooter";
  /* @hfdefault-start */
  function sanitizeHeaderFooterDefault(hf) {
    if (!hf || typeof hf !== "object") return null;
    var out = JSON.parse(JSON.stringify(hf));
    if (out.header && typeof out.header === "object") delete out.header.title;
    if (out.footer && Array.isArray(out.footer.children)) {
      out.footer.children.forEach(function (ch) { if (ch && ch.type === "courseNav") ch.sections = []; });
    }
    return out;
  }
  function headerFooterFromDefault(savedDefault, title) {
    if (!savedDefault || typeof savedDefault !== "object") return null;
    var out = JSON.parse(JSON.stringify(savedDefault));
    out.header = out.header || {};
    out.header.title = title; // always the NEW course's own name, never the source course's
    return out;
  }
  /* @hfdefault-end */
  window.__hfDefault = { sanitize: sanitizeHeaderFooterDefault, fromDefault: headerFooterFromDefault };
  function getHeaderFooterDefault() {
    try { var s = localStorage.getItem(HF_DEFAULT_KEY); return s ? JSON.parse(s) : null; } catch (e) { return null; }
  }
  // Schema-CSV import rebuilds the whole doc from the CSV, which would overwrite the
  // house header/footer default with whatever (often blank) HF the CSV carries. Expose
  // the machine default so importSchema can keep it: returns the default HF for `title`,
  // or null when no house default has been set (then the CSV's own HF is left alone).
  window.__hfDefault.forNewDoc = function (title) {
    var saved = getHeaderFooterDefault();
    return saved ? headerFooterFromDefault(saved, title) : null;
  };
  function saveHeaderFooterDefault() {
    var clean = sanitizeHeaderFooterDefault(doc.headerFooter);
    if (!clean) return false;
    if (clean.header && typeof clean.header.logo === "string") { // bake the logo -> portable data URI
      var m = /^asset:(.+)$/.exec(clean.header.logo);
      if (m && window.AssetStore) { var a = window.AssetStore.get(m[1]); if (a && a.dataUrl) clean.header.logo = a.dataUrl; }
    }
    try { localStorage.setItem(HF_DEFAULT_KEY, JSON.stringify(clean)); return true; } catch (e) { return false; }
  }
  function clearHeaderFooterDefault() { try { localStorage.removeItem(HF_DEFAULT_KEY); } catch (e) {} }

  function createBlankDoc(title, code) {
    if (registry[code]) {
      alert("A course with code '" + code + "' already exists.");
      return;
    }
    var newDoc = {
      meta: { title: title, code: code },
      backupRequired: true, // Slice 2: a new course MUST bind a backup folder (nagged until it does)
      headerFooter: headerFooterFromDefault(getHeaderFooterDefault(), title) || {
        header: { on: true, title: title, subtitle: "Course Orientation", logo: null },
        footer: { on: true, text: "WARNING: This document may contain technical data subject to export control laws." }
      },
      pages: [
        {
          id: "intro",
          name: "Introduction",
          blocks: [
            { type: "heading", text: title },
            { type: "paragraph", text: "Welcome to the " + title + " course." }
          ]
        }
      ]
    };
    registry[code] = newDoc;
    saveRegistry(registry);
    openDocIds.push(code);
    saveOpenDocIds(openDocIds);
    switchDoc(code);
  }

  function importDocToRegistry(importedDoc) {
    var code = importedDoc.meta.code || ("IMPORTED-" + Math.floor(Math.random() * 1000));
    importedDoc.meta.code = code;
    // Commit + load. Wrapped so any failure is VISIBLE: native alert()/confirm()
    // are swallowed by the Verso WKWebView host (no WKUIDelegate panels), so the
    // old raw confirm()/alert() here failed silently -> "picked a file, nothing
    // happened". Route the overwrite prompt through the DOM confirmModal and log
    // every step so a failed import self-reports in the Web Inspector console.
    function commit() {
      try {
        registry[code] = importedDoc;
        saveRegistry(registry);
        if (openDocIds.indexOf(code) === -1) {
          openDocIds.push(code);
          saveOpenDocIds(openDocIds);
        }
        switchDoc(code);
        if (window.console && console.log) console.log("[import] loaded course '" + code + "'");
      } catch (e) {
        if (window.console && console.error) console.error("[import] commit failed:", e);
        confirmModal("Import failed", "Could not load the course: " + (e && e.message || e), function () {});
      }
    }
    if (registry[code]) {
      confirmModal("Overwrite existing course?",
        "A course with code '" + code + "' already exists. Overwrite it?",
        commit, { danger: true, okLabel: "Overwrite" });
      return;
    }
    commit();
  }

  // Read a picked .verso/.json course file and hand the parsed doc to onDoc.
  // Factored out of showNewDocDialog so the file browser (#74) reuses the exact
  // same read/parse/error path. Native alert() is swallowed by the WKWebView host,
  // so every failure routes through the DOM confirmModal.
  function readCourseFile(file, onDoc) {
    if (!file) return;
    var isVerso = /\.verso$/i.test(file.name || "");
    var reader = new FileReader();
    reader.onerror = function () {
      var err = reader.error;
      if (window.console && console.error) console.error("[import] FileReader error:", err);
      confirmModal("Import failed",
        "Could not read the file" + (err && err.name ? " (" + err.name + ")" : "") + ". It may be too large for this app's memory.",
        function () {});
    };
    reader.onload = function () {
      try {
        var imported;
        if (isVerso) {
          var pkg = window.VersoFormat.readPackage(new Uint8Array(reader.result));
          if (window.AssetStore) Object.keys(pkg.assets).forEach(function (id) {
            window.AssetStore.put(pkg.assets[id].dataUrl, { mime: pkg.assets[id].mime });
          });
          imported = pkg.doc;
        } else {
          imported = JSON.parse(reader.result);
        }
        if (!imported || !imported.pages) {
          confirmModal("Import failed", "That file isn't a valid course document (no pages found).", function () {});
          return;
        }
        if (window.console && console.log) console.log("[import] parsed OK: " + (imported.pages || []).length + " pages from " + file.name);
        onDoc(imported);
      } catch (e) {
        if (window.console && console.error) console.error("[import] parse/import failed:", e);
        confirmModal("Import failed", (isVerso ? "Invalid .verso: " : "Invalid JSON: ") + (e && e.message || e), function () {});
      }
    };
    if (isVerso) reader.readAsArrayBuffer(file); else reader.readAsText(file);
  }
  function pickCourseFile(onDoc) {
    var input = document.createElement("input");
    input.type = "file"; input.accept = ".json,application/json,.verso";
    input.addEventListener("change", function () { readCourseFile(input.files && input.files[0], onDoc); });
    input.click();
  }

  function showNewDocDialog() {
    var existing = document.getElementById("new-doc-modal");
    if (existing) return;

    // Import / sample sit in the footer beside Cancel + Create blank; the whole
    // dialog routes through the DS modal shell (VersoUI.Modal) — issue #19. modal
    // + box are assigned from the shell below.
    var modal, box, titleIn, codeIn;
    var btnImport = window.VersoUI.Button({ variant: "secondary", label: "Import…", onClick: function () {
      pickCourseFile(function (imported) { importDocToRegistry(imported); modal.remove(); });
    } });
    var btnSample = window.VersoUI.Button({ variant: "secondary", label: "Load sample copy", onClick: function () {
      var code = "DEMO-WSE-101-copy-" + Math.floor(Math.random() * 1000);
      var freshSample = clone(window.SAMPLE_DOC || doc);
      freshSample.meta.code = code;
      freshSample.meta.title += " (Copy)";
      importDocToRegistry(freshSample);
      modal.remove();
    } });

    var shell = dsModalShell({
      id: "new-doc-modal", keys: false,
      title: "New document",
      subtitle: "Open a saved course, import a document, or start a blank one.",
      extras: [btnImport, btnSample],
      primaryLabel: "Create blank",
      onPrimary: function () {
        var title = titleIn.value.trim();
        var code = codeIn.value.trim();
        if (!title || !code) { alert("Title and Code are required."); return; }
        createBlankDoc(title, code);
        modal.remove();
        // Slice 2: MANDATORY backup-folder setup — prompt the picker immediately (still
        // within this click gesture, required for the native/FSA folder pickers). If the
        // author cancels, the loud "no backup folder" banner nags until they bind.
        bindProjectFolder();
      }
    });
    modal = shell.modal; box = shell.body;

    var closedIds = Object.keys(registry).filter(function (id) {
      return openDocIds.indexOf(id) === -1;
    });
    if (closedIds.length > 0) {
      modalSection(box, "Open a saved course");
      var list = h("div", "modal-list");
      closedIds.forEach(function (id) {
        var d = registry[id];
        var item = h("div", "modal-list__item");
        var left = h("div", "insp-list__text");
        left.appendChild(h("span", "insp-list__title", d.meta.title || id));
        left.appendChild(h("span", "insp-list__meta", id));
        item.appendChild(left);
        item.addEventListener("click", function () {
          openDocIds.push(id);
          saveOpenDocIds(openDocIds);
          switchDoc(id);
          modal.remove();
        });
        // Delete a saved (closed) course from the registry. Confirm first; permanent
        // local removal (any exported SCORM / on-disk backup folder is left alone).
        var del = iconBtn("trash", "Delete this saved course", true);
        del.addEventListener("click", function (e) {
          e.stopPropagation(); // don't open the course we're deleting
          confirmModal("Delete course?", "Permanently remove “" + (d.meta.title || id) + "” (" + id + ") from this machine. This can't be undone. Any exported SCORM or backup folder on disk is not affected.", function () {
            delete registry[id];
            saveRegistry(registry);
            var oi = openDocIds.indexOf(id); if (oi !== -1) { openDocIds.splice(oi, 1); saveOpenDocIds(openDocIds); }
            modal.remove(); showNewDocDialog(); // re-render the list fresh
          }, { okLabel: "Delete", danger: true });
        });
        item.appendChild(del);
        list.appendChild(item);
      });
      box.appendChild(list);
    }

    modalSection(box, "New course");
    titleIn = modalText(box, "Course title", "", "e.g. My New Course");
    codeIn = modalText(box, "Course code", "", "e.g. DRO-NEW-101");
  }

  // ---- history / undo-redo -------------------------------------------------
  var undoStack = [];
  var redoStack = [];
  var MAX_HISTORY = 50;
  var hasPushedForFocus = false;

  function pushHistory() {
    if (doc == null) return; // kit-gallery / pre-boot: nothing to snapshot
    undoStack.push(clone(doc));
    if (undoStack.length > MAX_HISTORY) {
      undoStack.shift();
    }
    redoStack = [];
    updateHistoryButtons();
  }
  // Which page indices differ between two doc snapshots — or null if the change
  // isn't page-isolatable (page count/order/id changed, or a doc-level field like
  // chapters/theme/headerFooter/variants differs), meaning a full mount is needed.
  // Lets undo/redo of a single-block edit rebuild ONE page instead of the whole
  // world (every HTML-interaction iframe) — the Ctrl+Z lag on embed-heavy courses.
  function isolatedPageChanges(prev, next) {
    if (!prev || !next) return null;
    var pp = prev.pages || [], np = next.pages || [];
    if (pp.length !== np.length) return null;
    for (var i = 0; i < pp.length; i++) if ((pp[i] && pp[i].id) !== (np[i] && np[i].id)) return null;
    function shell(d) { var o = {}; Object.keys(d).forEach(function (k) { if (k !== "pages") o[k] = d[k]; }); return JSON.stringify(o); }
    if (shell(prev) !== shell(next)) return null; // a doc-level field changed -> full rebuild
    var changed = [];
    for (var j = 0; j < pp.length; j++) if (JSON.stringify(pp[j]) !== JSON.stringify(np[j])) changed.push(j);
    return changed;
  }
  // #50: mirrors setDoc's doc/registry pair-write — undo/redo used to touch only `doc`,
  // leaving registry[activeDocId] stale so the next save persisted the pre-undo doc.
  function restoreSnapshot(next) {
    var prev = doc;
    var changed = isPreview() ? null : isolatedPageChanges(prev, next);
    doc = next;
    registry[activeDocId] = next;
    if (changed) {
      clearSelection();
      if (changed.length) reapplyStructural(changed); else { renderStructure(); renderModelView(); }
    } else {
      mount();
    }
    if (typeof rebindTourBuilderToLiveDoc === "function") rebindTourBuilderToLiveDoc(); // keep an open builder bound to the restored doc
    updateHistoryButtons();
  }
  function undo() {
    if (undoStack.length === 0) return;
    redoStack.push(clone(doc));
    restoreSnapshot(undoStack.pop());
  }
  function redo() {
    if (redoStack.length === 0) return;
    undoStack.push(clone(doc));
    restoreSnapshot(redoStack.pop());
  }
  function updateHistoryButtons() {
    if (undoBtn) undoBtn.disabled = undoStack.length === 0;
    if (redoBtn) redoBtn.disabled = redoStack.length === 0;
  }

