  // Product Rail (source-topic-content-authoring): the facets object to read/write for
  // a given column -- Flagship writes straight onto the section; a variant column
  // writes into its (already-diverged, by the time this is called) override.
  function facetsRefFor(sec, variant) {
    if (variant == null) { sec.facets = sec.facets || {}; return sec.facets; }
    sec.overrides = sec.overrides || {};
    sec.overrides[variant] = sec.overrides[variant] || { facets: {} };
    sec.overrides[variant].facets = sec.overrides[variant].facets || {};
    return sec.overrides[variant].facets;
  }
  function stampTopicUpdated(topic) { topic.updatedAt = Date.now(); saveLibrary(); }

  // Drag state for the section grip handle (source-stage-section-disclosure) -- only the
  // handle itself is draggable=true (the section box holds an editable heading input and
  // body text, so making the whole box draggable would fight text selection); the
  // surrounding .source-stage__section box is the drop target. Same shape as the
  // outliner's `treeDrag` (editor.js ~16310), reusing its drop-marker classes.
  var __sourceSectionDrag = null; // { id } | null
  // Which single (section, variant) body cell is currently in edit mode -- click a
  // rendered body to swap it for a real contentEditable surface (seeded with the SAME
  // MarkdownLite.render() HTML the view shows, so entering edit mode never flashes raw
  // ** markers); blur commits + swaps back. Everything else keeps reading as normal
  // MarkdownLite output, so browsing a topic never shows raw markdown -- only the one
  // cell an author is actively typing into, and even that cell reads as formatted text.
  var __sourceEditingCell = null; // { sectionId, variant } | null

  // Bold/inline-code/bullet-list toolbar for the ACTIVE contentEditable cell -- built
  // fresh per editing cell (closes over that cell's own element directly, so no shared
  // "active field" global is needed the way the old textarea-splicing toolbar used).
  // Same io.getNode()/io.onChange() adapter SHAPE as the canvas inspector's
  // buildFormatToggleBar (editor.js ~13223) for consistency, though Source stage keeps
  // its own smaller button set (Bold/code/bullet, not italic/underline/link) since
  // "list" here means an inline execCommand bullet toggle, not FORMAT_TOGGLES'
  // "list-block" whole-block-type conversion -- a different operation entirely.
  function buildSourceEditToolbar(io) {
    var toolbar = h("div", "source-stage__edit-toolbar");
    function execAndCommit(cmd, arg) {
      return function () {
        var node = io.getNode(); if (!node) return;
        node.focus();
        document.execCommand(cmd, false, arg || null);
        io.onChange();
      };
    }
    // No native execCommand wraps a selection in <code> -- surround it manually. A
    // collapsed (empty) selection is a no-op (nothing to wrap), same guard the old
    // marker-toggle had for an insertion point with no text selected.
    function wrapInlineCode() {
      var node = io.getNode(); if (!node) return;
      node.focus();
      var sel = window.getSelection();
      if (!sel || !sel.rangeCount) return;
      var range = sel.getRangeAt(0);
      if (range.collapsed) return;
      var codeEl = document.createElement("code");
      try { range.surroundContents(codeEl); }
      catch (e) { codeEl.appendChild(range.extractContents()); range.insertNode(codeEl); }
      sel.removeAllRanges();
      var after = document.createRange(); after.selectNodeContents(codeEl); after.collapse(false);
      sel.addRange(after);
      io.onChange();
    }
    [{ label: "B", icon: null, title: "Bold", action: execAndCommit("bold") },
     { label: null, icon: "code-xml", title: "Inline code", action: wrapInlineCode },
     { label: null, icon: "list", title: "Bullet list", action: execAndCommit("insertUnorderedList") }]
      .forEach(function (t) {
        var btn = h("button", "prop-toggle" + (t.icon ? " prop-toggle--icon" : ""));
        btn.type = "button"; btn.title = t.title;
        if (t.icon) btn.innerHTML = Icon(t.icon); else btn.textContent = t.label;
        btn.addEventListener("mousedown", function (e) { e.preventDefault(); }); // keep the field's selection
        btn.addEventListener("click", t.action);
        toolbar.appendChild(btn);
      });
    return toolbar;
  }
  // Commits an edited cell's contentEditable content back to markdown-lite text. Guards
  // against a purely cosmetic open/close (click in, click away, nothing typed) ever
  // rewriting the stored string: some of render()'s own behaviour is lossy in one
  // direction (e.g. a multi-line paragraph with no blank-line separators collapses its
  // newlines to spaces), so a naive round-trip of UNCHANGED content could still come out
  // textually different from the original -- which would falsely look like an edit to
  // the re-import reconcile system (#87/#88's lastImportedText comparisons). Comparing
  // against a re-serialize of the OLD text's own rendered form (not the old text
  // itself) means "no real edit happened" is judged the same lossy way render() itself
  // already behaves, so it never fires on a no-op.
  function commitEditableCell(topic, sec, variant, editEl) {
    var ref = facetsRefFor(sec, variant);
    var oldText = ref[__sourceActiveFacet] || "";
    var newText = window.MarkdownLite.serialize(editEl);
    var probe = document.createElement("div");
    probe.innerHTML = window.MarkdownLite.render(oldText);
    var normalizedOld = window.MarkdownLite.serialize(probe);
    if (newText !== normalizedOld) {
      ref[__sourceActiveFacet] = newText;
      stampTopicUpdated(topic);
    }
  }

  // md-topic-import: lets the author compare their current (Flagship) text against a
  // re-imported source's version once reconcileSection has flagged a real conflict, and
  // pick a side -- "Use updated text" applies the source's version (and clears the flag);
  // "Keep mine" dismisses the flag without changing anything; Cancel leaves it pending.
  function openSourceUpdateModal(topic, sec) {
    var shell = dsModalShell({
      title: "Source updated",
      subtitle: (sec.heading || "This section") + " changed both here and in the re-imported source since the last import.",
      primaryLabel: "Use updated text",
      extras: window.VersoUI ? [window.VersoUI.Button({
        variant: "secondary", label: "Keep mine",
        onClick: function () { delete sec.sourceUpdate; stampTopicUpdated(topic); shell.modal.close(); renderSourceArticle(); }
      })] : [],
      onPrimary: function () {
        sec.facets.technical = sec.sourceUpdate.text;
        sec.lastImportedText = sec.sourceUpdate.text;
        delete sec.sourceUpdate;
        stampTopicUpdated(topic);
        shell.modal.close();
        renderSourceArticle();
      }
    });
    // product-rail-review-diff: a real line-level diff (LineDiff, classic LCS) instead of
    // two flat side-by-side blocks -- removed lines (your text) and added lines (the
    // source's) are visually distinguished so the actual change is legible at a glance.
    modalSection(shell.body, "What changed");
    var diffBlock = h("div", "source-stage__diff-block");
    var ops = window.LineDiff ? window.LineDiff.diff(sec.facets.technical || "", sec.sourceUpdate.text || "") : [];
    ops.forEach(function (op) {
      var prefix = op.type === "removed" ? "− " : op.type === "added" ? "+ " : "  ";
      diffBlock.appendChild(h("div", "source-stage__diff-line source-stage__diff-line--" + op.type, prefix + op.text));
    });
    shell.body.appendChild(diffBlock);
  }

  // source-stage-comments: the same feedback/discussion system the canvas editor already
  // has (makeComment/makeReply, comment-popover/comment-thread/comment-row CSS), ported
  // to Source stage. Storage lives on the topic itself (topic.comments), not doc.comments
  // -- Product Rail topics are library content (window.LibraryStore), not part of any
  // course doc. Anchor is section-scoped ({sectionId}, no dx/dy/pageId -- there's no
  // canvas/zoom here to project a pixel position from). No floating pin/popover either:
  // Source stage never uses floating overlays anywhere (the flag pill, diverge row,
  // variant pills are all plain inline siblings, full-rerender on every state change) --
  // an inline expand/collapse thread panel matches that established convention, not the
  // canvas's own (structurally different: infinite pan/zoom needs a pin anchored in
  // screen space; a normal scrolling document doesn't).
  var __sourceOpenCommentSectionId = null; // which section's thread panel is expanded, or null

  // One comment's rendered row: the SAME .comment-reply/.comment-row__dot/.comment-
  // popover__row/.comment-popover__del classes the canvas comment system already
  // defines in editor.css (plain flex rows, nothing canvas/position-specific), reused
  // verbatim rather than styled twice.
  // opts.onChange (optional): fired after any mutation (resolve/delete/reply) so a mark-anchored
  // thread can log the event to History + refresh its pinned card, instead of the default section
  // path's full renderSourceArticle. Defaults to renderSourceArticle when omitted (the #94 path).
  function buildSourceCommentItem(topic, c, opts) {
    var UI = window.VersoUI;
    var after = (opts && opts.onChange) || function () { stampTopicUpdated(topic); renderSourceArticle(); };
    var item = h("div", "source-stage__comment-item");
    var line = h("div", "comment-reply");
    var dot = h("span", "comment-row__dot"); dot.style.background = c.colour || "";
    var body = h("span", "comment-reply__body");
    body.textContent = (c.author ? c.author + ": " : "") + (c.body || "");
    line.appendChild(dot); line.appendChild(body);
    item.appendChild(line);
    var row = h("div", "comment-popover__row");
    if (UI && UI.Checkbox) {
      var doneCheck = UI.Checkbox({
        checked: !!c.done, label: "Resolved",
        onChange: function (v) { c.done = v; after("resolve", c); }
      });
      row.appendChild(doneCheck);
    }
    var del = h("button", "comment-popover__del", "Delete");
    del.addEventListener("click", function () {
      var i = (topic.comments || []).indexOf(c);
      if (i !== -1) topic.comments.splice(i, 1);
      after("delete", c);
    });
    row.appendChild(del);
    item.appendChild(row);
    (c.replies || []).forEach(function (rp) {
      var rl = h("div", "comment-reply");
      var rd = h("span", "comment-row__dot"); rd.style.background = rp.colour || "";
      var rb = h("span", "comment-reply__body"); rb.textContent = (rp.author ? rp.author + ": " : "") + (rp.body || "");
      rl.appendChild(rd); rl.appendChild(rb); item.appendChild(rl);
    });
    if (UI && UI.TextField && UI.Button) {
      var replyField = UI.TextField({ value: "", placeholder: "Reply…" });
      replyField.classList.add("comment-reply__input");
      var replyBtn = UI.Button({
        variant: "secondary", label: "Reply",
        onClick: function () {
          var v = (replyField.input.value || "").trim(); if (!v) return;
          c.replies = c.replies || []; c.replies.push(makeReply(v));
          after("reply", c);
        }
      });
      item.appendChild(replyField); item.appendChild(replyBtn);
    }
    return item;
  }
  // The expanded thread panel for one section: every comment anchored to it, then a
  // fresh "Add a comment" field at the bottom.
  function buildSourceCommentPanel(topic, sec) {
    var UI = window.VersoUI;
    var panel = h("div", "comment-thread source-stage__comment-panel");
    sourceCommentsForSection(topic, sec.id).forEach(function (c) { panel.appendChild(buildSourceCommentItem(topic, c)); });
    if (UI && UI.TextField && UI.Button) {
      var newField = UI.TextField({ multiline: true, rows: 2, value: "", placeholder: "Add a comment…" });
      newField.classList.add("comment-popover__body");
      var addBtn = UI.Button({
        variant: "primary", label: "Comment",
        onClick: function () {
          var v = (newField.input.value || "").trim(); if (!v) return;
          topic.comments = topic.comments || [];
          topic.comments.push(makeComment({ sectionId: sec.id }, v));
          stampTopicUpdated(topic); renderSourceArticle();
        }
      });
      panel.appendChild(newField); panel.appendChild(addBtn);
    }
    return panel;
  }

  function renderSourceArticle() {
    if (typeof document === "undefined") return;
    var host = document.getElementById("source-stage-article"); if (!host) return;
    host.innerHTML = "";
    var topic = __sourceActiveTopicId ? libComponents()[__sourceActiveTopicId] : null;
    // the all-marks drawer belongs to the continuous-document view only -- drop it when the
    // active topic isn't a doc topic (the doc path re-syncs it against the live model below).
    if (!(topic && topicHasDoc(topic))) { __sourceActiveMarkId = null; closeSourceAltPanel(); closeSourceWherePanel(); closeSourceCommentThread(); }
    if (!topic || topic.kind !== "topic") {
      host.appendChild(h("div", "source-stage__empty", "Select a topic to read it."));
      renderSourceInfoPanel(null);
      return;
    }
    var headEl = h("div", "source-stage__article-head");
    var titleInput = h("input", "source-stage__title source-stage__title-input");
    titleInput.type = "text"; titleInput.value = topic.name || "";
    titleInput.placeholder = "Untitled topic";
    titleInput.addEventListener("change", function () {
      topic.name = titleInput.value.trim();
      stampTopicUpdated(topic);
      renderSourceTopicList(); // the left-nav row label must stay in sync
    });
    headEl.appendChild(titleInput);

    // Source rewrite: a topic that has been converted to the continuous-document model renders
    // the new node-model article (lock + toolbars + marks) instead of the section+facet article.
    if (topicHasDoc(topic)) {
      host.appendChild(headEl);
      renderSourceNodeArticle(topic, host);
      renderSourceInfoPanel(topic);
      return;
    }

    var U = window.VersoUI;
    if (U && U.SegmentedControl) {
      headEl.appendChild(U.SegmentedControl({
        options: [{ value: "technical", label: "Technical" }, { value: "digestible", label: "Digestible" }, { value: "dotpoint", label: "Dot-point" }],
        value: __sourceActiveFacet,
        onChange: function (v) { if (!isValidFacet(v)) return; __sourceActiveFacet = v; renderSourceArticle(); }
      }));
    }
    host.appendChild(headEl);

    var pillsRow = buildVariantPillsRow(topic);
    if (pillsRow) host.appendChild(pillsRow);

    (topic.sections || []).forEach(function (sec, secIdx) {
      var secEl = h("div", "source-stage__section");
      // Attach BEFORE building children (not at the end of the loop body) -- a
      // contentEditable can only receive real focus once it's actually in the live
      // document, and editEl.focus() below runs while this section is still being
      // constructed. Latent in the old textarea version too (ta.focus() there was
      // silently a no-op for the same reason); surfaced now by the no-op commit guard's
      // own browser-verify, worth fixing properly rather than carrying forward.
      host.appendChild(secEl);

      var headingRow = h("div", "source-stage__heading-row");
      var headingInput = h("input", "source-stage__heading source-stage__heading-input");
      headingInput.type = "text"; headingInput.value = sec.heading || ""; headingInput.placeholder = "Section heading";
      headingInput.addEventListener("change", function () { sec.heading = headingInput.value; stampTopicUpdated(topic); });
      headingRow.appendChild(headingInput);
      // md-topic-import re-import safety: this section changed BOTH here and in a
      // re-imported source since the last import -- never silently overwritten (see
      // MarkdownImport.reconcileSection), just flagged for a manual look. The canonical
      // Badge (small status pill, design-system/components/structure/Badge) made
      // clickable -- it takes no onClick itself, but returns a plain DOM node.
      if (sec.sourceUpdate && window.VersoUI && window.VersoUI.Badge) {
        var flagPill = window.VersoUI.Badge({ children: "Source updated", tone: "warning" });
        flagPill.classList.add("source-stage__source-flag");
        flagPill.title = "This section changed in the source since you last edited it here. Click to review.";
        flagPill.addEventListener("click", function () { openSourceUpdateModal(topic, sec); });
        headingRow.appendChild(flagPill);
      }
      // Hover/focus-disclosed (source-stage-section-disclosure): hidden until you're
      // actually looking at this section, so the article reads as content first, not a
      // wall of controls. A drag handle replaces the old up/down button pair (drag IS the
      // reorder affordance); delete stays behind its existing confirm, just no longer
      // permanently on display.
      var actions = h("div", "source-stage__section-actions");
      var gripBtn = iconBtn("grip", "Drag to reorder");
      gripBtn.setAttribute("draggable", "true");
      gripBtn.addEventListener("dragstart", function (e) {
        __sourceSectionDrag = { id: sec.id };
        try { e.dataTransfer.effectAllowed = "move"; e.dataTransfer.setData("text/plain", ""); } catch (_) {}
        e.stopPropagation();
      });
      gripBtn.addEventListener("dragend", function () { __sourceSectionDrag = null; clearTreeMarks(); });
      secEl.addEventListener("dragover", function (e) {
        if (!__sourceSectionDrag || __sourceSectionDrag.id === sec.id) return;
        e.preventDefault(); e.stopPropagation();
        var r = secEl.getBoundingClientRect();
        secEl.__after = (e.clientY - r.top) > r.height / 2;
        clearTreeMarks();
        secEl.classList.add(secEl.__after ? "tree-drop-after" : "tree-drop-before");
      });
      secEl.addEventListener("dragleave", function () { secEl.classList.remove("tree-drop-before", "tree-drop-after"); });
      secEl.addEventListener("drop", function (e) {
        if (!__sourceSectionDrag) return;
        e.preventDefault(); e.stopPropagation();
        var dragId = __sourceSectionDrag.id, after = secEl.__after;
        __sourceSectionDrag = null; clearTreeMarks();
        structMoveSection(topic, dragId, sec.id, after);
        stampTopicUpdated(topic); renderSourceArticle();
      });
      // source-stage-comments: always clickable (starting the first comment needs an
      // affordance even at zero), a count Badge overlays it only once there's something
      // to show -- same iconButtonWithBadge (notification-bell) convention the Needs-
      // review chip already established, not a new "only show when non-empty" pattern.
      var openCommentCount = sourceCommentsForSection(topic, sec.id).filter(function (c) { return !c.done; }).length;
      var commentBtn = iconBtn("message-square", "Comments");
      commentBtn.classList.toggle("is-on", __sourceOpenCommentSectionId === sec.id);
      commentBtn.addEventListener("click", function () {
        __sourceOpenCommentSectionId = (__sourceOpenCommentSectionId === sec.id) ? null : sec.id;
        renderSourceArticle();
      });
      var delBtn = iconBtn("trash-2", "Delete this section", true);
      delBtn.addEventListener("click", function () {
        confirmModal("Delete section", (sec.heading || "This section") + " will be removed from the topic.", function () {
          removeSection(topic, secIdx); stampTopicUpdated(topic); renderSourceArticle();
        });
      });
      actions.appendChild(gripBtn);
      actions.appendChild(iconButtonWithBadge(commentBtn, openCommentCount));
      actions.appendChild(delBtn);
      headingRow.appendChild(actions);
      secEl.appendChild(headingRow);

      var cols = sectionColumns(sec, __sourceActiveVariants, __sourceActiveFacet);
      var columned = cols.length > 1;
      if (columned) secEl.classList.add("source-stage__section--columns");
      var colHost = columned ? h("div", "source-stage__col-grid") : secEl;
      if (columned) colHost.style.gridTemplateColumns = "repeat(" + cols.length + ", minmax(0, 1fr))";
      cols.forEach(function (c) {
        var wrap = columned ? h("div", "source-stage__col") : secEl;
        if (columned) wrap.appendChild(h("div", "source-stage__col-label", c.variant == null ? "Flagship" : c.variant));
        var editing = __sourceEditingCell && __sourceEditingCell.sectionId === sec.id && __sourceEditingCell.variant === c.variant;
        if (editing) {
          // A real contentEditable, seeded with the SAME rendered HTML the view shows --
          // never a raw markdown-lite string in a textarea. Widen the section while
          // editing so the whole block stays visible instead of clipping to the normal
          // reading-width column.
          secEl.classList.add("source-stage__section--editing");
          var editEl = h("div", "source-stage__body source-stage__body--editing");
          editEl.contentEditable = "true";
          editEl.innerHTML = window.MarkdownLite ? window.MarkdownLite.render(c.text) : "";
          var toolbar = buildSourceEditToolbar({ getNode: function () { return editEl; }, onChange: function () {} });
          wrap.appendChild(toolbar);
          editEl.addEventListener("blur", function () {
            commitEditableCell(topic, sec, c.variant, editEl);
            __sourceEditingCell = null;
            renderSourceArticle();
          });
          wrap.appendChild(editEl);
          editEl.focus();
          // land the cursor at the end, ready to type
          var range = document.createRange(); range.selectNodeContents(editEl); range.collapse(false);
          var sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(range);
        } else {
          var bodyEl = h("div", "source-stage__body");
          bodyEl.innerHTML = window.MarkdownLite ? window.MarkdownLite.render(c.text) : "";
          bodyEl.title = "Click to edit";
          bodyEl.addEventListener("click", function () { __sourceEditingCell = { sectionId: sec.id, variant: c.variant }; renderSourceArticle(); });
          wrap.appendChild(bodyEl);
        }
        if (columned) colHost.appendChild(wrap);
      });
      if (columned) secEl.appendChild(colHost);

      // Diverge affordance: any variant currently toggled but NOT yet diverged for
      // this section doesn't get a column from sectionColumns (by design -- see
      // source-stage-variant-columns), so offer to start one instead of hiding it.
      var notDiverged = __sourceActiveVariants.filter(function (v) { return sectionOverrideVariants(sec).indexOf(v) === -1; });
      if (notDiverged.length) {
        var divergeRow = h("div", "source-stage__diverge-row");
        notDiverged.forEach(function (v) {
          var dBtn = h("button", "source-stage__diverge-btn", "Diverge for " + v);
          dBtn.type = "button";
          dBtn.addEventListener("click", function () {
            divergeSectionVariant(sec, v, clone);
            stampTopicUpdated(topic);
            renderSourceArticle();
          });
          divergeRow.appendChild(dBtn);
        });
        secEl.appendChild(divergeRow);
      }

      if (__sourceOpenCommentSectionId === sec.id) secEl.appendChild(buildSourceCommentPanel(topic, sec));
    });

    var addBtn = h("button", "source-stage__add-section", "+ Add section");
    addBtn.type = "button";
    addBtn.addEventListener("click", function () {
      addSection(topic);
      stampTopicUpdated(topic);
      renderSourceArticle();
    });
    host.appendChild(addBtn);

    // Source rewrite on-ramp (Epic 2b): opt a topic into the continuous-document model. Additive
    // and reversible -- the section data is kept, so a revert restores the section article.
    if (window.SourceDoc) {
      var convertRow = h("div", "source-stage__convert-row");
      var convertBtn = h("button", "source-stage__convert-btn", "Switch to continuous document (beta)");
      convertBtn.type = "button";
      convertBtn.title = "Re-author this topic as one continuous rich-text document with range marks (the new Source model)";
      convertBtn.addEventListener("click", function () { convertTopicToDoc(topic); });
      convertRow.appendChild(convertBtn);
      host.appendChild(convertRow);
    }

    renderSourceInfoPanel(topic);
  }

  // Product Rail (source-stage-info-panel): "Linked in" (where-used, jumps to the
  // referencing document -- Epic 4's lock/fork tickets are what will ever populate
  // this list; the panel + its empty state are correct before that data exists) +
  // "History" (created/last-updated, reusing the same relative-time formatter recents
  // already uses). Reuses the canonical panelSection() helper, not a one-off block --
  // this is a plain info panel, not a block-inspector taxonomy section (sectionGroup's
  // TAXONOMY/reorder system is specific to that surface, not this one).
  // The ONE consolidated right panel (Source v2, spec 2c section 3). It replaces the old pair --
  // an always-on info aside PLUS an overlay all-marks drawer that stacked on top of it (the
  // "double-up") -- with a single panel of canonical sections in navigator order: Marks (the mark
  // navigator, folded in from the drawer) / History / Source (provenance + where-used) / Comments.
  function renderSourceInfoPanel(topic) {
    if (typeof document === "undefined") return;
    var host = document.getElementById("source-stage-info"); if (!host) return;
    host.innerHTML = "";
    if (!topic) return;
    // Marks -- the navigator, first (only when the topic is a continuous document with a live model)
    if (topicHasDoc(topic)) renderSourceMarksSection(host, ensureSourceDocModel(topic));
    // History
    renderHistoryTimeline(host, topic);
    // Source -- provenance (which manual file/version/publish date this came from), then where the
    // document is used downstream ("Linked in N"). Both are document-origin facts, so they share
    // one section instead of the old separate top-of-panel "Linked in" block.
    var sourceBody = panelSection(host, "Source", { collapsible: true });
    if (topic.source) {
      sourceBody.appendChild(h("div", "insp-hint", topic.source.file || "Unknown file"));
      var meta = [topic.source.version, topic.source.publishDate].filter(Boolean).join(" · ");
      if (meta) sourceBody.appendChild(h("div", "insp-hint", meta));
      (Object.keys(topic.variantSources || {})).forEach(function (v) {
        var vs = topic.variantSources[v];
        var line = v + ": " + (vs.file || "Unknown file") + ([vs.version, vs.publishDate].filter(Boolean).length ? " (" + [vs.version, vs.publishDate].filter(Boolean).join(" · ") + ")" : "");
        sourceBody.appendChild(h("div", "insp-hint", line));
      });
    } else {
      sourceBody.appendChild(h("div", "insp-hint", "Authored in Verso (no imported source)."));
    }
    var used = libraryWhereUsedDetail(topic.id, getRegistry());
    sourceBody.appendChild(h("div", "source-info__subhead", "Linked in (" + used.length + ")"));
    if (!used.length) {
      sourceBody.appendChild(h("div", "insp-hint", "Not currently linked in any document."));
    } else {
      used.forEach(function (u) {
        var row = h("button", "source-stage__linked-row", u.docTitle);
        row.type = "button";
        row.title = "Open " + u.docTitle;
        row.addEventListener("click", function () { openCourseFromBrowser(u.docCode); setStage("edit"); });
        sourceBody.appendChild(row);
      });
    }
    // Comments
    renderSourceCommentsPanel(host, topic);
    applySourceInfoVisibility();
  }
  // Show or hide the one consolidated panel (its single doc-bar toggle). Hidden -> the reading
